  Object.assign(window.CONTENT_ICON || (window.CONTENT_ICON = {}), { a2l: "flame", "gas-heat": "flame", airflow: "cycle", psychro: "drop", "elec-depth": "bolt", "chp5-install": "wrench", "chp5-service": "gauge" });
