  if (window.CHP5_MAP) window.CHP5_MAP["FOUND-A2L-01"] = (window.CHP5_MAP["FOUND-A2L-01"] || []).concat(["install", "service"]).filter((v, i, a) => a.indexOf(v) === i);

  /* ---------- EPA 608: new practice items aligned to EPA's public test topics ---------- */
  const E = window.EPA_QUESTIONS, ref = "EPA Section 608 test topics";
  const EQ = (qen, qes, ans, wen, wes) => Object.assign(Q(qen, qes, ans, wen, wes), { ref });
  if (E && E.core) E.core.push(
    EQ("A customer asks for a 'drop-in' replacement for R-22. The accurate answer is:", "Un cliente pide un reemplazo 'directo' (drop-in) del R-22. La respuesta correcta es:", [["There is no true drop-in; retrofits need checks of oil, components and charge", "No existe uno realmente directo; la reconversión requiere revisar aceite, componentes y carga"], ["R-410A is a drop-in for R-22", "El R-410A es un reemplazo directo del R-22"], ["Any HFC can be added on top of R-22", "Cualquier HFC se puede agregar encima del R-22"], ["Propane is approved as a drop-in", "El propano está aprobado como reemplazo directo"]], "Substitutes differ in pressure, oil compatibility and glide. Every retrofit follows the refrigerant and equipment maker's procedure.", "Los sustitutos difieren en presión, compatibilidad de aceite y deslizamiento. Cada reconversión sigue el procedimiento del fabricante."),
    EQ("Breathing high concentrations of refrigerant vapor can cause:", "Respirar altas concentraciones de vapor de refrigerante puede causar:", [["Oxygen deprivation and heart arrhythmia", "Falta de oxígeno y arritmia cardiaca"], ["Only mild eye irritation", "Solo leve irritación de ojos"], ["No effect; refrigerants are inert", "Ningún efecto; los refrigerantes son inertes"], ["Ozone poisoning", "Intoxicación por ozono"]], "Refrigerant vapor is heavier than air and displaces oxygen; it can also sensitize the heart. In extreme cases, use SCBA.", "El vapor de refrigerante es más pesado que el aire y desplaza el oxígeno; también puede afectar el corazón. En casos extremos se usa equipo de respiración autónomo (SCBA)."),
    EQ("In the U.S., production of CFC refrigerants such as R-12 ended on:", "En EE. UU., la producción de refrigerantes CFC como el R-12 terminó el:", [["January 1, 1996", "1 de enero de 1996"], ["January 1, 2010", "1 de enero de 2010"], ["January 1, 2020", "1 de enero de 2020"], ["July 1, 1992", "1 de julio de 1992"]], "CFC production for U.S. use ended at the start of 1996 under the Clean Air Act and Montreal Protocol. Recovered and reclaimed CFCs may still be used.", "La producción de CFC para uso en EE. UU. terminó al inicio de 1996 según la Ley de Aire Limpio y el Protocolo de Montreal. Los CFC recuperados y regenerados aún se pueden usar.")
  );
  if (E && E.type2) E.type2.push(
    EQ("Which sign suggests a leak in a high-pressure system?", "¿Qué señal sugiere una fuga en un sistema de alta presión?", [["Excessive superheat and oil traces at joints", "Sobrecalentamiento excesivo y rastros de aceite en las uniones"], ["Very low superheat", "Sobrecalentamiento muy bajo"], ["High subcooling", "Subenfriamiento alto"], ["Frequent purge-unit operation", "Operación frecuente de la unidad de purga"]], "Lost charge starves the evaporator (high superheat), and oil travels with escaping refrigerant. Excess purging is the low-pressure-system sign.", "La pérdida de carga deja sin refrigerante al evaporador (sobrecalentamiento alto) y el aceite sale con el refrigerante. La purga excesiva es la señal en sistemas de baja presión."),
    EQ("Why shouldn't you energize a hermetic compressor while the system is in a deep vacuum?", "¿Por qué no se debe energizar un compresor hermético con el sistema en vacío profundo?", [["Motor windings can short or arc and be damaged", "Los devanados pueden hacer corto o arco y dañarse"], ["It would vent refrigerant", "Ventearía refrigerante"], ["It makes the vacuum deeper", "Hace el vacío más profundo"], ["The vacuum pump would reverse", "La bomba de vacío giraría al revés"]], "Insulation strength drops in a vacuum, so the motor terminals and windings can be damaged.", "El aislamiento pierde resistencia en vacío, así que las terminales y devanados se pueden dañar.")
  );
  if (E && E.type3) E.type3.push(
    EQ("Before draining oil from a low-pressure chiller, heat the oil to about:", "Antes de drenar el aceite de un chiller de baja presión, calienta el aceite a unos:", [["130°F", "130°F"], ["70°F", "70°F"], ["212°F", "212°F"], ["32°F", "32°F"]], "Warm oil releases dissolved refrigerant, so less refrigerant leaves with the oil.", "El aceite tibio suelta el refrigerante disuelto, así que sale menos refrigerante con el aceite."),
    EQ("When charging an evacuated low-pressure chiller, you introduce:", "Al cargar un chiller de baja presión evacuado, introduces:", [["Vapor first, then liquid", "Primero vapor y luego líquido"], ["Liquid first", "Primero líquido"], ["Nitrogen with the refrigerant", "Nitrógeno con el refrigerante"], ["Only vapor, never liquid", "Solo vapor, nunca líquido"]], "Liquid entering a deep vacuum boils at a very low temperature and can freeze water in the tubes. Vapor first raises the pressure safely.", "El líquido que entra en vacío profundo hierve a muy baja temperatura y puede congelar el agua de los tubos. Primero vapor sube la presión de forma segura."),
    EQ("A centrifugal chiller is charged through the:", "Un chiller centrífugo se carga por la:", [["Evaporator charging valve", "Válvula de carga del evaporador"], ["Purge unit", "Unidad de purga"], ["Condenser relief valve", "Válvula de alivio del condensador"], ["Compressor discharge", "Descarga del compresor"]], "Charging through the evaporator charging valve is the standard practice.", "Cargar por la válvula de carga del evaporador es la práctica estándar.")
  );

